{
  "studies": [
    {
      "key": "neuron_culture_modulators",
      "description": "Primary mouse hippocampal neurons (DIV14) infected with lentiviral constructs driving human Aβ1-42 and/or wild type (WT) human Tau for 24 hrs, then treated with 10 μM Nilotinib (or 1 μL DMSO) for 24 hrs, 100 nM Bafilomycin-A1, and/or 20 μM MG132 for 6 hrs; Aβ1-42 and p-Tau Ser 396 measured by ELISA in cell extracts and media (Figure 1A-E)."
    },
    {
      "key": "m17_proteasome_assay",
      "description": "Chymotrypsin-like 20S proteasome activity assay in human M17 neuroblastoma cells co-transfected with Tau, LacZ or Aβ1-42 cDNAs and treated with Nilotinib, MG132 or Bafilomycin-A1 (Figure 1F)."
    },
    {
      "key": "tau_ko_neuron_culture",
      "description": "Primary hippocampal neurons prepared from C57BL/6 (WT) and homozygous Tau−/− mice, infected with lentiviral clones at DIV14 and treated with DMSO, Nilotinib, Bafilomycin-A1 and/or MG132; Aβ1-42 and p-Tau Ser 396 measured by ELISA (Figure 2A-B)."
    },
    {
      "key": "in_vivo_lentiviral_mice",
      "description": "WT (C57BL/6) and Tau−/− mice stereotaxically injected into the hippocampus with 1×106 MOI V5-tagged lentiviral human Tau, Aβ1-42, Tau ± Aβ1-42 adjusted with LacZ, and treated 3 weeks post-injection with daily 10 mg/kg I.P. Nilotinib or 30 μL DMSO for 3 additional weeks; total brain Aβ1-42 and p-Tau Ser 396 measured by ELISA (Figure 2C-D)."
    },
    {
      "key": "av_fractionation",
      "description": "Subcellular fractionation of brains of lentivirus-injected WT and Tau−/− mice treated with 10 mg/kg Nilotinib or DMSO, isolating AV10, AV20 and lysosomal fractions for human specific Aβ1-42 and Ser 396 p-Tau ELISA, with Western blot of Tau species and autophagy markers Beclin-1 and LC3-I/II (Figure 3)."
    },
    {
      "key": "ihc_ptau_stereology",
      "description": "Immunostaining of 20 μm thick coronal brain sections with p-Tau antibodies AT8 and AT180 counterstained with DAB and stereological quantification of p-Tau in hippocampus and cortex of lentivirus-injected WT and Tau−/− mice treated with Nilotinib or DMSO (Figure 4)."
    },
    {
      "key": "ihc_plaque",
      "description": "6E10 and DAB staining of 20 μm thick coronal sections of lentivirus-injected WT and Tau−/− mice treated with Nilotinib or DMSO, with stereological counting of Aβ1-42 positive cells and plaque number/mm2 in total brain (Figure 5)."
    },
    {
      "key": "cell_death_assays",
      "description": "Cupric silver staining of 20 μm thick coronal sections with stereological quantification of silver-positive cells, and caspase-3 activity assay, in lentivirus-injected WT and Tau−/− mice treated with Nilotinib or DMSO (Figure 6)."
